.darma-loader-darma-b7-liquid-wave-fill { --accent: var(--loader-color, #0ea5e9); --accent-2: var(--loader-secondary-color, #1d4ed8); width: var(--loader-size, 72px); height: var(--loader-size, 72px); border-radius: 50%; border: calc(var(--loader-size, 72px) * .05) solid color-mix(in srgb, var(--accent) 40%, transparent); position: relative; overflow: hidden; }
.darma-loader-darma-b7-liquid-wave-fill span { position: absolute; left: 50%; top: 45%; width: 170%; height: 170%; margin-left: -85%; background: linear-gradient(var(--accent), var(--accent-2)); border-radius: 42% 45% 41% 47%; animation: darma-loader-darma-b7-liquid-wave-fill-wave-spin calc(var(--loader-speed, 1s) * 3) linear infinite, darma-loader-darma-b7-liquid-wave-fill-wave-rise calc(var(--loader-speed, 1s) * 4) ease-in-out infinite alternate; }
@keyframes darma-loader-darma-b7-liquid-wave-fill-wave-spin { to { transform: rotate(360deg); } }
@keyframes darma-loader-darma-b7-liquid-wave-fill-wave-rise { 0% { top: 60%; } 100% { top: 22%; } }

